//! Subscribes to all Guardian topics and prints every event as one JSON line
//! on stdout, e.g. `guardian-monitor > run-042.jsonl` for the evidence collector.
//!
//! This is the consumer side of the Guardian's output: what a DFM bridge or
//! evidence collector would see. Each line looks like
//! `{"rx_ms": ..., "topic": "fault", "message_id": "...", "event": {...}}`.
//! Lines may arrive out of order across topics; sort by `event.seq`.

use std::str::FromStr;
use std::sync::Arc;

use async_trait::async_trait;
use clap::Parser;
use guardian::config::GuardianConfig;
use guardian::contract::resource;
use guardian::service::now_ms;
use guardian::transport;
use up_rust::{UListener, UMessage, UTransport, UUri};

#[derive(Parser)]
struct Args {
    #[arg(short, long)]
    config: Option<std::path::PathBuf>,
    #[arg(long)]
    zenoh_config: Option<String>,
    /// Do not print heartbeats.
    #[arg(long)]
    no_heartbeat: bool,
}

/// Listener that prints every received Guardian message.
struct Printer {
    no_heartbeat: bool,
}

#[async_trait]
impl UListener for Printer {
    async fn on_receive(&self, msg: UMessage) {
        // The resource ID of the source uUri tells which topic it came from.
        let topic = match msg.source().map(|s| s.resource_id()) {
            Some(resource::HEARTBEAT) if self.no_heartbeat => return,
            Some(resource::HEARTBEAT) => "heartbeat",
            Some(resource::STATE) => "state",
            Some(resource::FAULT) => "fault",
            Some(resource::MITIGATION) => "mitigation",
            _ => "unknown",
        };
        // Payload as generic JSON: we only pass it through, no need for the structs.
        let event: serde_json::Value = msg
            .payload
            .as_ref()
            .and_then(|p| serde_json::from_slice(p).ok())
            .unwrap_or(serde_json::Value::Null);
        let line = serde_json::json!({
            "rx_ms": now_ms(),
            "topic": topic,
            "message_id": msg.id().map(|id| id.to_hyphenated_string()),
            "event": event,
        });
        println!("{line}");
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    transport::init_logging();
    let args = Args::parse();
    // Same config file as the Guardian, to know its entity ID.
    let cfg = match &args.config {
        Some(path) => GuardianConfig::load(path)?,
        None => GuardianConfig::default(),
    };
    let up = &cfg.uprotocol;
    let zenoh_config = args.zenoh_config.as_deref().or(up.zenoh_config.as_deref());
    let transport = transport::zenoh_transport(&up.authority, zenoh_config).await?;

    // //*/8002/1/FFFF = any authority, the Guardian entity, any resource
    // (FFFF is the wildcard), i.e. all four Guardian topics at once.
    let filter = UUri::from_str(&format!(
        "//*/{:X}/{:X}/FFFF",
        up.entity_id, up.entity_version
    ))?;
    let listener = Arc::new(Printer {
        no_heartbeat: args.no_heartbeat,
    });
    transport.register_listener(&filter, None, listener).await?;
    // Messages are now printed by the listener; just wait for Ctrl-C.
    tokio::signal::ctrl_c().await?;
    Ok(())
}
